INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chimei','赤眉','["汉","赤眉军"]',NULL,'cn','east_asia',23,1,NULL,'year',27,1,NULL,'year',276,324,'ochre',NULL,NULL,'新莽末赤眉起义军政权，樊崇为首，25年立刘盆子为帝，27年降刘秀。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('nanyue','南越','["南越","南越国"]',NULL,'cn','east_asia',-203,1,NULL,'year',-111,1,NULL,'year',-2424,-1320,'ochre',NULL,NULL,'赵佗据岭南自立，前203年建国；前111年汉武帝遣军灭南越，设九郡。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fan-chong','樊崇','chimei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["起义领袖"]','樊崇是琅邪起义军首领，率赤眉军反抗王莽，军中以眉毛涂红相别。赤眉拥立刘盆子后入关中；刘秀围困其军，樊崇最终归降并死于洛阳。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/樊崇"},{"label":"《后汉书》刘盆子传","url":"https://zh.wikisource.org/wiki/後漢書/卷11"}]',NULL,NULL,'赤眉首领','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-panzi','刘盆子','chimei','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','刘盆子是城阳景王刘章后裔，赤眉军在长安拥立他为帝。刘秀军击败赤眉后，刘盆子于27年投降，获封列侯；其后在洛阳生活。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘盆子"},{"label":"《后汉书·刘盆子传》（维基文库）","url":"https://zh.wikisource.org/wiki/後漢書/卷11"}]',NULL,NULL,'赤眉帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-jiande','赵建德','nanyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','赵建德由丞相吕嘉拥立，是南越末王。汉武帝派军南下后，吕嘉与赵建德逃亡，最终被汉军俘获；前111年南越灭亡，岭南纳入汉郡县体系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵建德"},{"label":"《史记·南越列传》（中国哲学书电子化计划）","url":"https://ctext.org/shiji/nan-yue-lie-zhuan/zhs"}]',NULL,NULL,'南越王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-mo','赵眜','nanyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','赵眜是赵佗之孙，南越文王。其墓在广州象岗出土，出土的“文帝行玺”金印等器物为确认其身份及南越王室制度提供了考古证据；死后由赵婴齐继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵眜"},{"label":"《史记·南越列传》（中国哲学书电子化计划）","url":"https://ctext.org/shiji/nan-yue-lie-zhuan/zhs"}]',NULL,NULL,'南越文王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-tuo','赵佗','nanyue','[]',NULL,NULL,-240,1,NULL,'year',-137,1,NULL,'year','["君主"]','赵佗原为秦将，秦末任南海尉；秦亡后兼并桂林、象郡，自立南越武王。汉初接受册封并维持岭南自治，传至孙赵眜时南越继续与汉朝往来。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵佗"},{"label":"《史记·南越列传》（中国哲学书电子化计划）","url":"https://ctext.org/shiji/nan-yue-lie-zhuan/zhs"}]',NULL,NULL,'南越武王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-xing','赵兴','nanyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','赵兴年幼继承南越王位，其母樛太后主张入朝归汉。丞相吕嘉反对并发动政变，杀赵兴及樛太后；汉武帝随后出兵，南越于前111年并入汉朝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵兴"},{"label":"《史记·南越列传》（中国哲学书电子化计划）","url":"https://ctext.org/shiji/nan-yue-lie-zhuan/zhs"}]',NULL,NULL,'南越王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-yingqi','赵婴齐','nanyue','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','赵婴齐是赵眜之子，曾在长安为宿卫，赵眜死后回南越即位。他接受汉廷册封，死后其子赵兴继位，南越与汉朝关系随后因吕嘉之乱急剧转变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵婴齐"},{"label":"《史记·南越列传》（中国哲学书电子化计划）","url":"https://ctext.org/shiji/nan-yue-lie-zhuan/zhs"}]',NULL,NULL,'南越明王','[]');
